package com.zy.zhangyun;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
public class LoginActivity extends Activity { EditText server,user,pass; TextView error; Button savedServers; RadioGroup modelProvider; ApiClient api; ExecutorService pool=Executors.newSingleThreadExecutor(); List<ApiClient.ServerProfile> profiles=new ArrayList<>(); public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_login);api=new ApiClient(this);server=findViewById(R.id.server);user=findViewById(R.id.username);pass=findViewById(R.id.password);error=findViewById(R.id.error);savedServers=findViewById(R.id.savedServers);modelProvider=findViewById(R.id.modelProvider);server.setText(api.base());findViewById(R.id.login).setOnClickListener(v->login());loadSavedServers();} void loadSavedServers(){profiles=api.serverProfiles();savedServers.setText(profiles.isEmpty()?"已保存服务器 ▾（暂无）":"已保存服务器 ▾（"+profiles.size()+"）");savedServers.setOnClickListener(v->{if(profiles.isEmpty()){Toast.makeText(this,"登录成功后会自动保存此服务器",Toast.LENGTH_SHORT).show();return;}String[] labels=new String[profiles.size()];for(int i=0;i<profiles.size();i++)labels[i]=profiles.get(i).label();new AlertDialog.Builder(this).setTitle("选择服务器").setItems(labels,(dialog,which)->selectServer(profiles.get(which))).show();});if(!profiles.isEmpty())selectServer(profiles.get(0));} void selectServer(ApiClient.ServerProfile profile){api.activateServer(profile);server.setText(api.base());user.setText(profile.user);pass.setText(profile.password);} void login(){error.setText("");api.setBase(server.getText().toString().trim());String provider=modelProvider.getCheckedRadioButtonId()==R.id.openaiModel?"openai":"ollama";pool.execute(()->{try{boolean ok=api.login(user.getText().toString(),pass.getText().toString(),provider);runOnUiThread(()->{if(ok){startActivity(new Intent(this,ChooseActivity.class));finish();}else error.setText("账号或密码错误");});}catch(Exception e){android.util.Log.e("AIGirlfriend","Login connection failed",e);runOnUiThread(()->error.setText("连接失败："+e.getClass().getSimpleName()));}});}}
